	/** 
	 * jumpstart the process by instantiating2 Clinician
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		clinicianId = ClinicianService.getClinicianInstance()
		.createClinician( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ClinicianService.getClinicianInstance()
				.createClinician( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.clinicianSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Clinician : " + successValue.getClinicianId());
							  if (successValue.getClinicianId().equals(clinicianId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfClinicianList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Clinician test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on clinician consumed")
					);
			subscriber.clinicianSubscribe( clinicianId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Clinician : " + successValue.getClinicianId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfClinicianList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on clinician for clinicianId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Clinician. 
	 */
	protected Clinician read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Clinician" );

		Clinician entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Clinician with primary key" );
		msg.append( clinicianId );
		
		ClinicianFetchOneSummary fetchOneSummary = new ClinicianFetchOneSummary( clinicianId );

		try {
			entity = ClinicianService.getClinicianInstance().getClinician( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Clinician " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Clinician.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Clinician." );

		StringBuilder msg = new StringBuilder( "Failed to update a Clinician : " );        
		Clinician entity = read();
		UpdateClinicianCommand command = generateUpdateCommand();
		command.setClinicianId(entity.getClinicianId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Clinician." );

			// for use later on...
			clinicianId = entity.getClinicianId();

			ClinicianService proxy = ClinicianService.getClinicianInstance();  

			proxy.updateClinician( command ).get();

			LOGGER.info( "-- Successfully saved Clinician - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + clinicianId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Clinician.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Clinician." );

		Clinician entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Clinician with id " + clinicianId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Clinician with id " + clinicianId );

			throw e;
		}

		try{
			ClinicianService.getClinicianInstance().delete( new DeleteClinicianCommand( entity.getClinicianId() ) ).get();
			LOGGER.info( "-- Successfully deleted Clinician with id " + clinicianId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Clinician with id " + clinicianId );

			throw e;
		}
	}

	/**
	 * get all Clinicians.
	 */
	protected List<Clinician> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Clinicians:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Clinician : " );        
		List<Clinician> collection  = new ArrayList<>();

		try {
			// call the static get method on the ClinicianService
			collection = ClinicianService.getClinicianInstance().getAllClinician();
			assertNotNull( collection, "An Empty collection of Clinician was incorrectly returned.");
			
			// Now print out the values
			Clinician entity = null;            
			Iterator<Clinician> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getClinicianId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

